215	     */
216	    private boolean isDuplicateOwner(Owner owner) {
217	        return this.clinicService.findAllOwners().stream()
218	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
219	    }
220	
221	    /**
222	     * Determines whether the given owner's email address is already used by another owner. An owner
223	     * without an email address never conflicts. The comparison is case-insensitive and ignores
224	     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
225	     * {@code "john.smith@example.com"} are treated as the same address.
226	     *
227	     * @param owner the candidate owner to check
228	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
229	     */
230	    private boolean isDuplicateEmail(Owner owner) {
231	        String email = normalize(owner.getEmail());
232	        if (email == null || email.isEmpty()) {
233	            return false;
234	        }
235	        return this.clinicService.findAllOwners().stream()
236	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
237	    }
