239	    /**
240	     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
241	     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
242	     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
243	     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
244	     *
245	     * @param value the raw value, may be {@code null}
246	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
247	     */
248	    private static String normalize(String value) {
249	        if (value == null) {
250	            return null;
251	        }
252	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
253	    }
